<script setup lang="ts">
import {ElButton, ElInput, ElTable, ElTableColumn, ElPagination, ElCheckbox, ElCheckboxGroup} from 'element-plus'
import {ref,watch} from 'vue'
import {api,ApiError} from '../../api'
import {base,reasonText,type DiningStaff,type MemberChoice} from './types'
const props=defineProps<{restaurantId:string;canManage:boolean}>()
const items=ref<DiningStaff[]>([]),query=ref(''),choices=ref<MemberChoice[]>([]),selected=ref<MemberChoice|null>(null),permissions=ref<string[]>(['products','orders']),enabled=ref(true),busy=ref(false),error=ref(''),notice=ref(''),page=ref(1),total=ref(0),revision=ref(0)
let generation=0
watch(query,()=>{choices.value=[];selected.value=null;revision.value=0;generation++},{flush:'sync'})
async function load(){const current=generation;error.value='';try{const result=await api<{items:DiningStaff[];total:number}>(`${base}/restaurants/${props.restaurantId}/staff?page=${page.value}&pageSize=20`);if(current===generation){items.value=result.items;total.value=result.total}}catch(e){if(current===generation)error.value=reasonText(e)}}
async function search(){if(busy.value)return;const current=++generation;busy.value=true;error.value='';try{const result=await api<{members:MemberChoice[]}>(`${base}/restaurants/${props.restaurantId}/staff?${new URLSearchParams({memberSearch:query.value.trim()})}`);if(current===generation){choices.value=result.members;if(!choices.value.length)error.value='未找到已启用会员，请核对编号或昵称。'}}catch(e){if(current===generation)error.value=reasonText(e)}finally{busy.value=false}}
async function save(){if(!props.canManage||!selected.value||busy.value)return;busy.value=true;error.value='';notice.value='';try{await api(`${base}/restaurants/${props.restaurantId}/staff`,{method:'POST',body:JSON.stringify({memberId:selected.value.id,permissions:[...permissions.value],enabled:enabled.value,revision:revision.value})});query.value='';selected.value=null;await load();notice.value='人员授权已保存。'}catch(e){error.value=reasonText(e)+(e instanceof ApiError&&e.status===409?'；当前授权草稿已保留，请重新读取核对最新授权。':'')}finally{busy.value=false}}
function edit(item:DiningStaff){query.value=item.memberNo;selected.value={id:item.memberId,name:item.name,memberNo:item.memberNo};permissions.value=[...item.permissions];enabled.value=item.enabled;revision.value=item.revision}
watch(()=>props.restaurantId,()=>{generation++;items.value=[];query.value='';error.value='';load()},{immediate:true})
</script>
<template><section class="panel"><h2>餐饮店管理人员</h2><p>选择已注册会员，授权后可在小程序个人中心进入联盟中心。</p><p v-if="error" role="alert" class="error">{{error}} <el-button @click="load">重新读取</el-button></p><p v-if="notice" role="status">{{notice}}</p><el-table :data="items" empty-text="尚未授权管理人员"><el-table-column prop="name" label="会员"/><el-table-column prop="memberNo" label="会员编号"/><el-table-column label="权限"><template #default="{row}">{{row.permissions.map((p:string)=>({products:'商品',orders:'订单',finance:'佣金'}[p as 'products']||p)).join('、')}}</template></el-table-column><el-table-column label="状态"><template #default="{row}">{{row.enabled?'已授权':'已停用'}}</template></el-table-column><el-table-column v-if="canManage" label="操作"><template #default="{row}"><el-button link @click="edit(row as DiningStaff)">编辑授权</el-button></template></el-table-column></el-table><el-pagination :current-page="page" :total="total" :page-size="20" layout="prev,pager,next,total" @current-change="page=$event;load()"/><form v-if="canManage" @submit.prevent="save"><div class="toolbar"><el-input v-model="query" :disabled="busy" aria-label="查找会员" placeholder="输入会员编号或昵称" style="width:280px" @keydown.enter.prevent="search"/><el-button :disabled="busy||query.trim().length<2" @click="search">查找会员</el-button></div><ul v-if="choices.length"><li v-for="member in choices" :key="member.id">{{member.name}} · {{member.memberNo}} <el-button link @click="selected={...member};choices=[]">选择</el-button></li></ul><p v-if="selected" role="status">已选择：{{selected.name}} · {{selected.memberNo}}</p><div class="toolbar"><el-checkbox-group v-model="permissions" :disabled="busy"><el-checkbox value="products">商品上下架</el-checkbox><el-checkbox value="orders">订单</el-checkbox><el-checkbox value="finance">佣金</el-checkbox></el-checkbox-group><el-checkbox v-model="enabled" :disabled="busy">启用授权</el-checkbox><el-button native-type="submit" type="primary" :loading="busy" :disabled="!selected||!permissions.length">保存授权</el-button></div></form></section></template>
